import json
with open('after-cpm-packages.json') as f:
  content = f.read()
# Find the first { to skip any garbage
start = content.find('{')
if start >= 0:
  content = content[start:]
  # Find matching end
  depth = 0
  for i,c in enumerate(content):
    if c == '{': depth += 1
    elif c == '}': depth -= 1
    if depth == 0:
      content = content[:i+1]
      break
  data = json.loads(content)
  for proj in data.get('projects',[]):
    name = proj['path'].split('/')[-1]
    for fw in proj.get('frameworks',[]):
      for pkg in fw.get('topLevelPackages',[]):
        print(f'{name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
"", "description": "Parse packages from JSON"}
